package echo

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
	"testing"
)

// ---------- reference matcher implementing echo's documented semantics ----------

type refRes struct {
	pattern string
	params  map[string]string
	prio    []int
}

func refMatch(pattern, path string) (map[string]string, []int, bool) {
	// any route: '*' is the last segment and matches the rest of the path (possibly empty)
	if strings.HasSuffix(pattern, "/*") {
		base := pattern[:len(pattern)-1] // keep trailing '/'
		if !strings.HasPrefix(path, base) {
			return nil, nil, false
		}
		rest := path[len(base):]
		prio := make([]int, 0, 4)
		for _, s := range strings.Split(pattern, "/")[1:] {
			if s == "*" {
				prio = append(prio, 2)
			} else if strings.HasPrefix(s, ":") {
				prio = append(prio, 1)
			} else {
				prio = append(prio, 0)
			}
		}
		return map[string]string{"*": rest}, prio, true
	}
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
	if len(ps) != len(xs) {
		return nil, nil, false
	}
	params := map[string]string{}
	prio := make([]int, 0, len(ps))
	for i := range ps {
		switch {
		case i == 0 && ps[i] == "" && xs[i] == "":
			prio = append(prio, 0)
		case strings.HasPrefix(ps[i], ":"):
			if xs[i] == "" { // param matches exactly one non-empty segment
				return nil, nil, false
			}
			params[ps[i][1:]] = xs[i]
			prio = append(prio, 1)
		case ps[i] == xs[i]:
			prio = append(prio, 0)
		default:
			return nil, nil, false
		}
	}
	return params, prio, true
}

func prioLess(a, b []int) int {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		if a[i] != b[i] {
			if a[i] < b[i] {
				return -1
			}
			return 1
		}
	}
	return 0
}

// refBest returns the expected route (nil if none) and its params.
// Ties are reported as ambiguous (ok=false) and skipped by the caller.
func refBest(routes []string, path string) (string, map[string]string, bool) {
	var best []refRes
	for _, r := range routes {
		p, prio, ok := refMatch(r, path)
		if !ok {
			continue
		}
		best = append(best, refRes{r, p, prio})
	}
	if len(best) == 0 {
		return "", nil, true
	}
	sort.SliceStable(best, func(i, j int) bool { return prioLess(best[i].prio, best[j].prio) < 0 })
	if len(best) > 1 && prioLess(best[0].prio, best[1].prio) == 0 {
		return "", nil, false // ambiguous
	}
	return best[0].pattern, best[0].params, true
}

// ---------- harness ----------

func findSafe(t *testing.T, e *Echo, method, path string) (handler HandlerFunc, cpath string, pnames []string, pvalues []string, panicked interface{}) {
	c := e.NewContext(nil, nil).(*context)
	defer func() { panicked = recover() }()
	e.router.Find(method, path, c)
	return c.Handler(), c.Path(), c.ParamNames(), c.ParamValues(), nil
}

var fuzzRoutes = []string{
	"/", "/a", "/a/b", "/a/:id", "/a/*", "/:id", "/:id/b", "/*", "/a/:id/c", "/a/:id/*", "/ab", "/a/bc",
}

var fuzzPaths = []string{
	"/", "/a", "/a/", "/a/b", "/a/b/", "/a/b/c", "/a/b/c/", "/a/x", "/a/x/", "/a/x/c", "/a/x/c/",
	"/a/x/y", "/a/xy", "/ab", "/abc", "/a/bc", "/a/bcd", "/b", "/b/b", "/b/c", "/x/y/z", "//", "/a//b",
	"/a/b/c/d", "/A", "/a/B", "/a/:id", "/a/*", "/a/x/c/d", "/ab/c", "/a/b/c/d/e",
}

func TestRouterFuzzTmp(t *testing.T) {
	fails := 0
	report := func(format string, args ...interface{}) {
		fails++
		if fails <= 40 {
			t.Errorf(format, args...)
		}
	}

	// all subsets of fuzzRoutes (2^12 = 4096 combos)
	for mask := 0; mask < (1 << len(fuzzRoutes)); mask++ {
		var routes []string
		for i, r := range fuzzRoutes {
			if mask&(1<<uint(i)) != 0 {
				routes = append(routes, r)
			}
		}
		e := New()
		for _, r := range routes {
			e.router.Add(http.MethodGet, r, handlerFunc)
		}
		for _, p := range fuzzPaths {
			expRoute, expParams, ok := refBest(routes, p)
			if !ok {
				continue
			}
			h, cpath, pnames, pvalues, pan := findSafe(t, e, http.MethodGet, p)
			if pan != nil {
				report("PANIC routes=%v path=%q: %v", routes, p, pan)
				continue
			}
			if expRoute == "" {
				if h == nil {
					report("routes=%v path=%q: nil handler (expected NotFoundHandler)", routes, p)
					continue
				}
				if fmt.Sprintf("%p", h) != fmt.Sprintf("%p", NotFoundHandler) {
					report("routes=%v path=%q: got handler %p path=%q, expected NotFoundHandler", routes, p, h, cpath)
				}
				continue
			}
			if h == nil {
				report("routes=%v path=%q: nil handler, expected route %q", routes, p, expRoute)
				continue
			}
			if cpath != expRoute {
				report("routes=%v path=%q: selected route %q, expected %q", routes, p, cpath, expRoute)
				continue
			}
			got := map[string]string{}
			for i, n := range pnames {
				if i < len(pvalues) {
					got[n] = pvalues[i]
				}
			}
			for k, v := range expParams {
				if got[k] != v {
					report("routes=%v path=%q route=%q: param %q=%q, expected %q (pnames=%v pvalues=%v)", routes, p, cpath, k, got[k], v, pnames, pvalues)
				}
			}
		}
	}
	t.Logf("failures: %d", fails)
}

// 405 + no-routes + ServeHTTP status codes
func TestRouterFuzzTmpServeHTTP(t *testing.T) {
	// Echo with no routes at all
	e := New()
	for _, p := range []string{"/", "/a", "/a/b", "", "//"} {
		h, cpath, _, _, pan := findSafe(t, e, http.MethodGet, p)
		if pan != nil {
			t.Errorf("no-routes PANIC path=%q: %v", p, pan)
			continue
		}
		if h == nil || fmt.Sprintf("%p", h) != fmt.Sprintf("%p", NotFoundHandler) {
			t.Errorf("no-routes path=%q: handler=%p path=%q, expected NotFoundHandler", p, h, cpath)
		}
		req := httptest.NewRequest(http.MethodGet, p, nil)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		if rec.Code != http.StatusNotFound {
			t.Errorf("no-routes ServeHTTP path=%q: status %d, expected 404", p, rec.Code)
		}
	}

	// 405
	e = New()
	e.GET("/a", handlerFunc)
	e.POST("/a/b", handlerFunc)
	for _, tc := range []struct {
		method, path string
		status       int
	}{{"POST", "/a", 405}, {"GET", "/a/b", 405}, {"DELETE", "/a", 405}, {"GET", "/a", 200}, {"POST", "/a/b", 200}, {"GET", "/zzz", 404}} {
		req := httptest.NewRequest(tc.method, tc.path, nil)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		if rec.Code != tc.status {
			t.Errorf("ServeHTTP %s %s: status %d, expected %d", tc.method, tc.path, rec.Code, tc.status)
		}
	}
}

