package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
	"testing"
)

// ---------- reference matcher implementing echo's documented semantics ----------

type refRes struct {
	pattern string
	params  map[string]string
	prio    []int
}

func refMatch(pattern, path string) (map[string]string, []int, bool) {
	params := map[string]string{}
	prio := []int{}
	if pattern == "/" {
		if path == "/" {
			return params, []int{0}, true
		}
		return nil, nil, false
	}
	isAny := strings.HasSuffix(pattern, "/*")
	body := pattern
	if isAny {
		body = pattern[:len(pattern)-1] // literal prefix up to and including '/'
	}
	psegs := strings.Split(strings.TrimSuffix(body, "/"), "/")
	xsegs := strings.Split(path, "/")

	if isAny {
		if len(xsegs) <= len(psegs) {
			return nil, nil, false // path must contain the '/' following the prefix
		}
	} else if len(xsegs) != len(psegs) {
		return nil, nil, false
	}
	for i, s := range psegs {
		switch {
		case strings.HasPrefix(s, ":"):
			if xsegs[i] == "" { // param matches exactly one non-empty segment
				return nil, nil, false
			}
			params[s[1:]] = xsegs[i]
			prio = append(prio, 1)
		case s == xsegs[i]:
			prio = append(prio, 0)
		default:
			return nil, nil, false
		}
	}
	if !isAny {
		return params, prio, true
	}
	consumed := strings.Join(xsegs[:len(psegs)], "/") + "/"
	params["*"] = path[len(consumed):]
	prio = append(prio, 2)
	return params, prio, true
}

func prioLess(a, b []int) int {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		if a[i] != b[i] {
			if a[i] < b[i] {
				return -1
			}
			return 1
		}
	}
	return 0
}

// refBest returns the expected route (nil if none) and its params.
// Ties are reported as ambiguous (ok=false) and skipped by the caller.
func refBest(routes []string, path string) (string, map[string]string, bool) {
	var best []refRes
	for _, r := range routes {
		p, prio, ok := refMatch(r, path)
		if !ok {
			continue
		}
		best = append(best, refRes{r, p, prio})
	}
	if len(best) == 0 {
		return "", nil, true
	}
	sort.SliceStable(best, func(i, j int) bool { return prioLess(best[i].prio, best[j].prio) < 0 })
	if len(best) > 1 && prioLess(best[0].prio, best[1].prio) == 0 {
		return "", nil, false // ambiguous
	}
	return best[0].pattern, best[0].params, true
}

