	"/abc/d", "/abc/d/e", "/ab/c/d", "/a/bcd/e", "/a/bc/d/e", "/a/b/c/d/e/f/g", "/a/b/c/d/x/y",
}

// mutations of registered patterns: paths that are "close" to a route but not routable
func mutate(p string) []string {
	out := []string{p, p + "/", p + "/x", p + "x", p + "/x/y"}
	if i := strings.LastIndex(p, "/"); i > 0 {
		out = append(out, p[:i], p[:i]+"/", p[:i]+"/x", p[:i]+"/x/")
	}
	if strings.HasSuffix(p, "/*") {
		out = append(out, strings.TrimSuffix(p, "/*"), strings.TrimSuffix(p, "/*")+"/x")
	}
	return out
