func checkCombo(t *testing.T, routes []string, paths []string, report func(string, ...interface{}), doHTTP bool) {
	e := New()
	for _, r := range routes {
		pat := r
		e.router.Add(http.MethodGet, pat, func(c Context) error {
			c.Set("route", pat)
			return nil
		})
	}
	for _, p := range paths {
		expRoute, expParams, ok := refBest(routes, p)
		if !ok {
			continue
		}
		c := e.NewContext(nil, nil).(*context)
		var pan interface{}
		func() {
			defer func() { pan = recover() }()
			e.router.Find(http.MethodGet, p, c)
		}()
		if pan != nil {
			report("PANIC routes=%v path=%q: %v", routes, p, pan)
			continue
		}
		var herr error
		func() {
			defer func() { pan = recover() }()
			herr = c.Handler()(c)
		}()
		if pan != nil {
			report("PANIC(handler) routes=%v path=%q: %v", routes, p, pan)
			continue
		}
		gotRoute, _ := c.Get("route").(string)
		if expRoute == "" {
			if gotRoute != "" {
				report("routes=%v path=%q: matched route %q, expected no match (404)", routes, p, gotRoute)
			} else if herr != ErrNotFound {
				report("routes=%v path=%q: no match but handler returned %v, expected ErrNotFound", routes, p, herr)
			}
		} else {
			if gotRoute != expRoute {
				report("routes=%v path=%q: matched route %q, expected %q", routes, p, gotRoute, expRoute)
			} else if herr != nil {
				report("routes=%v path=%q route=%q: handler error %v", routes, p, expRoute, herr)
			}
			got := map[string]string{}
			for i, n := range c.ParamNames() {
				if i < len(c.ParamValues()) {
					got[n] = c.ParamValues()[i]
				}
			}
			for k, v := range expParams {
				if got[k] != v {
					report("routes=%v path=%q route=%q: param %q=%q, expected %q (pnames=%v pvalues=%v)", routes, p, expRoute, k, got[k], v, c.ParamNames(), c.ParamValues())
				}
			}
		}
		if doHTTP {
			req := httptest.NewRequest(http.MethodGet, p, nil)
			rec := httptest.NewRecorder()
			e.ServeHTTP(rec, req)
			want := http.StatusNotFound
			if expRoute != "" {
				want = http.StatusOK
			}
			if rec.Code != want {
				report("ServeHTTP routes=%v path=%q: status %d, expected %d", routes, p, rec.Code, want)
			}
		}
	}
}

func TestRouterFuzzTmp(t *testing.T) {
	fails := 0
	report := func(format string, args ...interface{}) {
		fails++
		if fails <= 30 {
			t.Errorf(format, args...)
		}
	}
	rnd := rand.New(rand.NewSource(1))
	for iter := 0; iter < 20000; iter++ {
		k := 1 + rnd.Intn(10)
		idx := rnd.Perm(len(fuzzPool))[:k]
		routes := make([]string, 0, k)
		paths := append([]string{}, fixedPaths...)
		for _, i := range idx {
			routes = append(routes, fuzzPool[i])
			paths = append(paths, mutate(fuzzPool[i])...)
		}
		checkCombo(t, routes, paths, report, iter%200 == 0)
	}
	// all subsets of size <= 3 of the pool, in pool order
	for i := range fuzzPool {
		checkCombo(t, []string{fuzzPool[i]}, append(fixedPaths, mutate(fuzzPool[i])...), report, true)
		for j := i + 1; j < len(fuzzPool); j++ {
			rs := []string{fuzzPool[i], fuzzPool[j]}
			checkCombo(t, rs, append(fixedPaths, mutate(fuzzPool[i])...), report, false)
			checkCombo(t, []string{fuzzPool[j], fuzzPool[i]}, append(fixedPaths, mutate(fuzzPool[i])...), report, false)
			for k := j + 1; k < len(fuzzPool); k++ {
				checkCombo(t, []string{fuzzPool[i], fuzzPool[j], fuzzPool[k]}, fixedPaths, report, false)
			}
		}
	}
	t.Logf("failures: %d", fails)
}

