// refTied returns all routes that match with the best (lowest) priority vector.
func refTied(routes []string, path string) []refRes {
	var best []refRes
	for _, r := range routes {
		p, prio, ok := refMatch(r, path)
		if !ok {
			continue
		}
		best = append(best, refRes{r, p, prio})
