	if len(best) == 0 {
		return nil
	}
	sort.SliceStable(best, func(i, j int) bool { return prioLess(best[i].prio, best[j].prio) < 0 })
	out := []refRes{best[0]}
	for _, b := range best[1:] {
		if prioLess(b.prio, best[0].prio) == 0 {
			out = append(out, b)
		}
	}
