// build a pool of patterns with globally unique param names
func buildPool() []string {
	var out []string
	segs := []string{"a", "b", "x"}
	idx := 0
	add := func(parts []string) {
		idx++
		var pat string
		pn := 0
		for _, p := range parts {
			if p == ":" {
				pn++
				pat += fmt.Sprintf("/:p%d_%d", idx, pn)
			} else {
				pat += "/" + p
			}
		}
		out = append(out, pat)
	}
	for _, a := range append(append([]string{}, segs...), ":", "*") {
		add([]string{a})
		for _, b := range append(append([]string{}, segs...), ":", "*") {
			if a == "*" {
				continue
			}
			add([]string{a, b})
			for _, c := range append(append([]string{}, segs...), ":", "*") {
				if a == "*" || b == "*" {
					continue
				}
				add([]string{a, b, c})
			}
		}
	}
	return out
}

func genPaths2() []string {
	out := []string{"/"}
	cur := []string{""}
	alpha := []string{"a", "b", "x"}
	for depth := 1; depth <= 4; depth++ {
		var next []string
		for _, c := range cur {
			for _, s := range alpha {
				next = append(next, c+"/"+s)
			}
		}
		out = append(out, next...)
		cur = next
	}
	return out
}

func TestExhaustive2Tmp(t *testing.T) {
	pool := buildPool()
	paths := genPaths2()
	t.Logf("pool=%d paths=%d", len(pool), len(paths))
	fails := 0
	report := func(format string, args ...interface{}) {
		fails++
		if fails <= 25 {
			t.Errorf(format, args...)
		}
	}
	run := func(routes []string) {
		e := New()
		for _, r := range routes {
			pat := r
			e.router.Add(http.MethodGet, pat, func(c Context) error {
				c.Set("route", pat)
				return nil
			})
		}
		for _, p := range paths {
			cands := refTied(routes, p)
			c := e.NewContext(nil, nil).(*context)
			var pan interface{}
			func() {
				defer func() { pan = recover() }()
				e.router.Find(http.MethodGet, p, c)
			}()
			if pan != nil {
				report("PANIC routes=%v path=%q: %v", routes, p, pan)
				continue
			}
			var herr error
			func() {
				defer func() { pan = recover() }()
				herr = c.Handler()(c)
			}()
			if pan != nil {
				report("PANIC(handler) routes=%v path=%q: %v", routes, p, pan)
				continue
			}
			gotRoute, _ := c.Get("route").(string)
			if len(cands) == 0 {
				if gotRoute != "" {
					report("routes=%v path=%q: matched %q, expected no match", routes, p, gotRoute)
				} else if herr != ErrNotFound {
					report("routes=%v path=%q: no match but handler returned %v", routes, p, herr)
				}
				continue
			}
			var cand *refRes
			for i := range cands {
				if cands[i].pattern == gotRoute {
					cand = &cands[i]
				}
			}
			if cand == nil {
				report("routes=%v path=%q: matched %q, expected one of %v", routes, p, gotRoute, patternsOf(cands))
				continue
			}
			if herr != nil {
				report("routes=%v path=%q route=%q: handler error %v", routes, p, gotRoute, herr)
			}
			got := map[string]string{}
			for i, n := range c.ParamNames() {
				if i < len(c.ParamValues()) {
					got[n] = c.ParamValues()[i]
				}
			}
			for k, v := range cand.params {
				if got[k] != v {
					report("routes=%v path=%q route=%q: param %q=%q expected %q (pnames=%v pvalues=%v)", routes, p, gotRoute, k, got[k], v, c.ParamNames(), c.ParamValues())
				}
			}
			// no stale/extra param values for names not in this route
			for i, n := range c.ParamNames() {
				if _, ok := cand.params[n]; !ok && i < len(c.ParamValues()) && c.ParamValues()[i] != "" {
					report("routes=%v path=%q route=%q: stale value for unused param %q=%q (pnames=%v pvalues=%v)", routes, p, gotRoute, n, c.ParamValues()[i], c.ParamNames(), c.ParamValues())
				}
			}
		}
	}
	for i := range pool {
		run([]string{pool[i]})
		for j := i + 1; j < len(pool); j++ {
			run([]string{pool[i], pool[j]})
			run([]string{pool[j], pool[i]})
			for k := j + 1; k < len(pool); k++ {
				run([]string{pool[i], pool[j], pool[k]})
			}
		}
	}
	t.Logf("failures: %d", fails)
}

func patternsOf(rs []refRes) []string {
	out := make([]string, 0, len(rs))
	for _, r := range rs {
		out = append(out, r.pattern)
	}
	return out
}
